// C++: Preventing False Sharing using Alignment
#include <cstddef>

// Architecture specific (e.g., X86)
constexpr size_t L1_CACHE_LINE = 64;

// Ensures the struct starts exactly on a cache line boundary.
// Used to separate data accessed by different threads.
struct alignas(L1_CACHE_LINE) PerThreadData {
    long long value;
    // Padding implied by alignas
};

// Creating an array guarantees each element uses its own cache line
PerThreadData thread_counters[8];
